const envelope = $json.body ?? $json;
const incoming = Array.isArray(envelope)
  ? envelope
  : Array.isArray(envelope.messages)
    ? envelope.messages
    : [envelope];

const store = $getWorkflowStaticData('global');
store.schemaVersion ??= 1;
store.seen ??= {};
store.cases ??= {};
store.pendingDigest ??= [];
store.metrics ??= { accepted: 0, duplicates: 0, rejected: 0 };

const nowIso = new Date().toISOString();
const normalize = (value) => String(value ?? '')
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .replace(/đ/g, 'd')
  .replace(/Đ/g, 'D')
  .toLowerCase();

const hash = (value) => {
  let h = 2166136261;
  for (let i = 0; i < value.length; i++) {
    h ^= value.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return (h >>> 0).toString(16).padStart(8, '0');
};

const asIso = (value) => {
  if (value == null || value === '') return nowIso;
  const numeric = Number(value);
  const candidate = Number.isFinite(numeric)
    ? new Date(numeric < 100000000000 ? numeric * 1000 : numeric)
    : new Date(value);
  return Number.isNaN(candidate.getTime()) ? nowIso : candidate.toISOString();
};

const draftReply = (intent, senderName) => {
  const name = senderName ? ' ' + senderName : '';
  if (intent === 'casual') {
    return [
      'Haha nghe vui đó' + name + ' 😄 Để mình xem rồi nhắn lại nhé.',
      'Cảm ơn' + name + ' nha 😄 Mình đang bận chút, lát mình trả lời kỹ hơn.'
    ];
  }
  return [
    'Mình đã nhận được tin. Mình kiểm tra và phản hồi sớm nhé.',
    'Cảm ơn bạn đã nhắn. Cho mình ít phút để xem lại thông tin.'
  ];
};

const classify = (rawText, senderRole) => {
  const text = normalize(rawText);
  const role = normalize(senderRole);
  const has = (pattern) => pattern.test(text);

  const poll = has(/\b(poll|vote|binh chon|chon phuong an|chon lua)\b/);
  const reaction = has(/\b(react|tha tim|tha like|bam like|xac nhan da doc|confirm da hieu)\b/);
  const approval = has(/\b(phe duyet|approve|approval|dong y|ky duyet|quyet dinh|xac nhan chap thuan)\b/);
  const money = has(/\b(thanh toan|chuyen khoan|bao gia|chi phi|ngan sach)\b/) || /\d[\d.,]*\s*(k|tr|trieu|vnd|dong)\b/.test(text);
  const incident = has(/\b(hong|loi|bao tri|sua may|may dung|ket may|ro ri|chay|khoi|keu bat thuong|mat dien|tai nan|su co|incident|broken|fault|maintenance)\b/);
  const procurement = has(/\b(het hang|het vat tu|thieu vat tu|can mua|mua them|dat hang|bo sung|ton kho|procurement|purchase|restock)\b/);
  const assignment = has(/\b(giao viec|phan cong|nhiem vu|assignment|hoan thanh|nop bao cao|deadline)\b/) || ((role.includes('senior') || role.includes('manager') || role.includes('boss') || role.includes('sep')) && has(/\b(nho|lam|gui|chuan bi|kiem tra)\b/));
  const workerReport = role.includes('worker') || role.includes('operator') || role.includes('cong nhan') || has(/\b(bao cao ca|tinh hinh ca|tai xuong|tai kho|san xuat|worker report)\b/);
  const deadline = has(/\b(hom nay|ngay mai|sang mai|chieu mai|gap|khan|truoc \d|deadline|due)\b/) || /\b\d{1,2}([:/h-]\d{1,2})?\s*(am|pm)?\b/.test(text);
  const casual = has(/\b(haha|hehe|hihi|lol|di ca phe|an trua|cuoi tuan|vui|chuc mung|cam on|thank|meme)\b/);
  const question = rawText.includes('?') || has(/\b(duoc khong|the nao|khi nao|o dau|why|how|when|can you)\b/);

  let lane = 'IGNORE-DIGEST';
  let intent = 'informational';
  let rationale = 'No action requested';

  if (poll) {
    lane = 'HUMAN-REQUIRED'; intent = 'poll-choice'; rationale = 'A person must choose; automation must not vote';
  } else if (reaction) {
    lane = 'HUMAN-REQUIRED'; intent = 'reaction-confirmation'; rationale = 'A reaction would represent the user';
  } else if (approval || money) {
    lane = 'HUMAN-REQUIRED'; intent = approval ? 'approval' : 'money-decision'; rationale = 'Approval, agreement, or money requires the user';
  } else if (incident) {
    lane = 'AUTO-HANDLE'; intent = 'maintenance-incident'; rationale = 'Track incident and follow-up';
  } else if (procurement) {
    lane = 'AUTO-HANDLE'; intent = 'procurement'; rationale = 'Create a procurement task without purchasing';
  } else if (assignment) {
    lane = 'AUTO-HANDLE'; intent = 'senior-assignment'; rationale = 'Track assignment and deadline';
  } else if (workerReport || deadline) {
    lane = 'AUTO-HANDLE'; intent = workerReport ? 'worker-report' : 'deadline'; rationale = 'Track operational update';
  } else if (casual || question) {
    lane = 'DRAFT-FOR-YOU'; intent = casual ? 'casual' : 'reply-needed'; rationale = 'Draft only; never impersonate the user';
  }

  const urgent = lane === 'HUMAN-REQUIRED' || (incident && has(/\b(dung|gap|khan|chay|khoi|tai nan|nguy hiem|ngay)\b/)) || (deadline && has(/\b(hom nay|gap|khan|ngay)\b/));
  const done = has(/\b(da xong|xong roi|hoan tat|da sua|resolved|fixed|completed|done)\b/);
  // Short workplace updates often omit the subject because it is obvious from
  // the conversation (for example, "đã PR rồi nhé"). Treat these as follow-ups,
  // but only promote them to tracked work when an open case exists in the same
  // conversation. This avoids inventing a task from an ambiguous standalone note.
  const terseStatus = has(/\b(da .{1,48} roi(?: nhe| nha)?|da (?:lam|gui|dat|tao|pr)\b|vua .{1,32} xong)\b/);
  const followUp = done || terseStatus || has(/\b(cap nhat|update|dang lam|dang sua|tho den|chua xong|tiep tuc|da goi)\b/);
  const deadlineMatch = rawText.match(/\b(hôm nay|ngày mai|sáng mai|chiều mai|trước[^,.!?;]{0,24}|\d{1,2}[:h]\d{0,2}|\d{1,2}[\/-]\d{1,2}(?:[\/-]\d{2,4})?)\b/i);
  return { lane, intent, rationale, urgent, done, followUp, deadline: deadlineMatch?.[0] ?? null };
};

const acceptedRecords = [];
const immediateAlerts = [];
let duplicateCount = 0;
let rejectedCount = 0;

for (const raw of incoming) {
  const text = String(raw.text ?? raw.message ?? raw.content ?? '').trim();
  const senderId = String(raw.sender_id ?? raw.senderId ?? raw.from?.id ?? raw.user_id ?? 'unknown');
  const senderName = String(raw.sender_name ?? raw.senderName ?? raw.from?.name ?? raw.user_name ?? 'Unknown sender');
  const senderRole = String(raw.sender_role ?? raw.senderRole ?? raw.role ?? 'unknown');
  const conversationId = String(raw.conversation_id ?? raw.conversationId ?? raw.thread_id ?? raw.chat_id ?? raw.from?.conversation_id ?? senderId);
  const timestamp = asIso(raw.timestamp ?? raw.created_at ?? raw.createdAt ?? raw.time);
  if (!text) {
    rejectedCount++;
    continue;
  }

  const suppliedId = raw.message_id ?? raw.messageId ?? raw.msgId ?? raw.id;
  const messageId = String(suppliedId ?? ('hash-' + hash([conversationId, senderId, timestamp, text].join('|'))));
  const dedupeKey = conversationId + ':' + messageId;
  if (store.seen[dedupeKey]) {
    duplicateCount++;
    continue;
  }
  store.seen[dedupeKey] = nowIso;

  const decision = classify(text, senderRole);
  const explicitCaseId = raw.case_id ?? raw.caseId ?? raw.reply_to_case_id ?? null;
  let caseId = explicitCaseId ? String(explicitCaseId) : null;
  if (!caseId && decision.followUp) {
    const candidates = Object.values(store.cases)
      .filter((item) => item.conversation_id === conversationId && item.status !== 'DONE')
      .sort((a, b) => String(b.updated_at).localeCompare(String(a.updated_at)));
    caseId = candidates[0]?.case_id ?? null;
  }
  const linkedCase = caseId ? store.cases[caseId] : null;
  if (linkedCase && decision.followUp && decision.lane === 'IGNORE-DIGEST') {
    decision.lane = 'AUTO-HANDLE';
    decision.intent = linkedCase.intent;
    decision.rationale = 'Status follow-up attached to the latest open case in this conversation';
  } else if (!linkedCase && decision.followUp && decision.lane === 'IGNORE-DIGEST') {
    decision.lane = 'DRAFT-FOR-YOU';
    decision.intent = 'reply-needed';
    decision.rationale = 'Ambiguous status update without an open case; show it and draft a clarification';
  }
  const needsCase = decision.lane === 'AUTO-HANDLE' || decision.lane === 'HUMAN-REQUIRED';
  if (!caseId && needsCase) caseId = 'CASE-' + hash(conversationId + '|' + decision.intent + '|' + timestamp);

  if (caseId && needsCase) {
    const existing = store.cases[caseId] ?? {
      case_id: caseId,
      conversation_id: conversationId,
      intent: decision.intent,
      status: 'OPEN',
      created_at: timestamp,
      messages: []
    };
    existing.intent = existing.intent === 'informational' ? decision.intent : existing.intent;
    existing.status = decision.done ? 'DONE' : existing.status;
    existing.updated_at = timestamp;
    existing.deadline = decision.deadline ?? existing.deadline ?? null;
    existing.messages.push({ message_id: messageId, timestamp, sender_id: senderId, text });
    existing.messages = existing.messages.slice(-50);
    store.cases[caseId] = existing;
  }

  const record = {
    message_id: messageId,
    dedupe_key: dedupeKey,
    conversation_id: conversationId,
    sender_id: senderId,
    sender_name: senderName,
    sender_role: senderRole,
    timestamp,
    text,
    case_id: caseId,
    lane: decision.lane,
    intent: decision.intent,
    urgent: decision.urgent,
    rationale: decision.rationale,
    deadline: decision.deadline,
    draft_replies: decision.lane === 'DRAFT-FOR-YOU' ? draftReply(decision.intent, senderName) : [],
    safety: {
      auto_react: false,
      auto_vote: false,
      auto_approve: false,
      auto_agree: false,
      auto_spend: false,
      auto_send_casual_reply: false
    }
  };
  acceptedRecords.push(record);
  store.pendingDigest.push(record);
  if (decision.urgent || decision.lane === 'HUMAN-REQUIRED') immediateAlerts.push(record);
}

store.pendingDigest = store.pendingDigest.slice(-500);
store.metrics.accepted += acceptedRecords.length;
store.metrics.duplicates += duplicateCount;
store.metrics.rejected += rejectedCount;
store.last_ingest_at = nowIso;

return [{
  json: {
    accepted: acceptedRecords.length,
    duplicates: duplicateCount,
    rejected: rejectedCount,
    immediate_count: immediateAlerts.length,
    immediate_alerts: immediateAlerts,
    notify: immediateAlerts.length > 0,
    notification_channel: 'TELEGRAM_PRIMARY',
    delivery_status: immediateAlerts.length ? 'WAITING_FOR_TELEGRAM_CREDENTIAL' : 'NOT_NEEDED',
    processed_at: nowIso,
    records: acceptedRecords
  }
}];

if (!$json.notify) return [];
const store = $getWorkflowStaticData('global');
store.notificationOutbox ??= [];
const alerts = $json.immediate_alerts ?? [];
const esc = (value) => String(value ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const clip = (value, max = 170) => {
  const text = String(value ?? '').replace(/\s+/g, ' ').trim();
  return text.length > max ? text.slice(0, max - 1) + '…' : text;
};
const time = (value) => new Intl.DateTimeFormat('vi-VN', {
  timeZone: 'Asia/Ho_Chi_Minh', hour: '2-digit', minute: '2-digit'
}).format(new Date(value));
const intentMeta = {
  'poll-choice': ['🗳️', 'BÌNH CHỌN', 'Chọn một phương án'],
  'reaction-confirmation': ['👍', 'XÁC NHẬN', 'React/xác nhận thủ công'],
  approval: ['✅', 'PHÊ DUYỆT', 'Bạn quyết định đồng ý hay từ chối'],
  'money-decision': ['💳', 'CHI PHÍ', 'Kiểm tra số tiền trước khi quyết định'],
  'maintenance-incident': ['🛠️', 'SỰ CỐ', 'Kiểm tra an toàn và phân công xử lý'],
  procurement: ['📦', 'MUA/BỔ SUNG', 'Xác nhận mức ưu tiên; chưa phát sinh mua'],
  'senior-assignment': ['📋', 'NHIỆM VỤ', 'Xem yêu cầu và thời hạn'],
  deadline: ['⏰', 'THỜI HẠN', 'Xác nhận ưu tiên'],
  'worker-report': ['🏭', 'BÁO CÁO XƯỞNG', 'Kiểm tra cập nhật']
};
const humanCount = alerts.filter((item) => item.lane === 'HUMAN-REQUIRED').length;
const urgentCount = alerts.filter((item) => item.urgent).length;
const blocks = alerts.slice(0, 6).map((item, index) => {
  const meta = intentMeta[item.intent] ?? ['🔔', String(item.intent || 'CẦN CHÚ Ý').toUpperCase(), 'Xem nội dung'];
  const priority = item.lane === 'HUMAN-REQUIRED' ? '🔴 CẦN BẠN' : '🟠 KHẨN';
  const deadline = item.deadline ? '⏰ ' + esc(item.deadline) : '⏰ Chưa ghi hạn';
  const caseRef = item.case_id ? '  •  <code>#' + esc(String(item.case_id).replace(/^CASE-/, '')) + '</code>' : '';
  return '<b>' + (index + 1) + '. ' + meta[0] + ' ' + esc(meta[1]) + '</b>  ·  <b>' + priority + '</b>\n' +
    '“' + esc(clip(item.text)) + '”\n' +
    '👤 ' + esc(item.sender_name) + '  •  🕘 ' + esc(time(item.timestamp)) + '  •  ' + deadline + caseRef + '\n' +
    '↳ <i>' + esc(meta[2]) + '</i>';
});
if (alerts.length > 6) blocks.push('<i>+' + (alerts.length - 6) + ' mục khác sẽ có trong bản tổng hợp.</i>');
const message = '<b>🚨 ZALO TRIAGE</b>  ·  ' + esc(time(new Date())) + '\n' +
  '🔴 ' + humanCount + ' cần bạn  •  🟠 ' + urgentCount + ' khẩn  •  📥 ' + alerts.length + ' mới\n\n' +
  blocks.join('\n\n') + '\n\n<i>Không tự trả lời, react, phê duyệt hay chi tiền.</i>';
const entry = {
  id: 'ALERT-' + Date.now(),
  channel: 'TELEGRAM',
  priority: 'IMMEDIATE',
  text: message,
  created_at: new Date().toISOString(),
  status: 'WAITING_FOR_CREDENTIAL'
};
store.notificationOutbox.push(entry);
store.notificationOutbox = store.notificationOutbox.slice(-200);
console.log('ZALO TRIAGE OUTBOX', JSON.stringify(entry));
return [{ json: { accepted: $json.accepted, duplicates: $json.duplicates, immediate_count: alerts.length, outbox_written: true, outbox_id: entry.id, telegram_text: entry.text, notify: true, delivery_status: entry.status } }];

const store = $getWorkflowStaticData('global');
store.pendingDigest ??= [];
store.notificationOutbox ??= [];
store.seen ??= {};
const now = new Date();
const pending = store.pendingDigest.splice(0, store.pendingDigest.length);
const grouped = {
  'AUTO-HANDLE': pending.filter((item) => item.lane === 'AUTO-HANDLE'),
  'DRAFT-FOR-YOU': pending.filter((item) => item.lane === 'DRAFT-FOR-YOU'),
  'HUMAN-REQUIRED': pending.filter((item) => item.lane === 'HUMAN-REQUIRED'),
  'IGNORE-DIGEST': pending.filter((item) => item.lane === 'IGNORE-DIGEST')
};

const esc = (value) => String(value ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const clip = (value, max = 125) => {
  const text = String(value ?? '').replace(/\s+/g, ' ').trim();
  return text.length > max ? text.slice(0, max - 1) + '…' : text;
};
const clock = (value) => new Intl.DateTimeFormat('vi-VN', {
  timeZone: 'Asia/Ho_Chi_Minh', hour: '2-digit', minute: '2-digit'
}).format(new Date(value));
const intentMeta = {
  'poll-choice': ['🗳️', 'Bình chọn', 'Chọn phương án'],
  'reaction-confirmation': ['👍', 'Xác nhận', 'React thủ công'],
  approval: ['✅', 'Phê duyệt', 'Quyết định đồng ý/từ chối'],
  'money-decision': ['💳', 'Chi phí', 'Kiểm tra và quyết định'],
  'maintenance-incident': ['🛠️', 'Sự cố', 'Đang theo dõi xử lý'],
  procurement: ['📦', 'Mua/bổ sung', 'Đã ghi việc; chưa đặt mua'],
  'senior-assignment': ['📋', 'Nhiệm vụ', 'Đang theo dõi'],
  deadline: ['⏰', 'Thời hạn', 'Đang theo dõi'],
  'worker-report': ['🏭', 'Báo cáo xưởng', 'Đã gắn vào luồng việc'],
  casual: ['💬', 'Bạn bè/đồng nghiệp', 'Bản nháp sẵn sàng'],
  'reply-needed': ['💬', 'Cần phản hồi', 'Bản nháp sẵn sàng']
};
const caseRef = (item) => item.case_id ? '  •  <code>#' + esc(String(item.case_id).replace(/^CASE-/, '')) + '</code>' : '';
const overflow = (items, shown) => items.length > shown ? '\n<i>+' + (items.length - shown) + ' mục khác đã được ghi lại.</i>' : '';
const humanLines = grouped['HUMAN-REQUIRED'].slice(0, 5).map((item) => {
  const meta = intentMeta[item.intent] ?? ['🔴', item.intent, 'Bạn xem và quyết định'];
  return '• ' + meta[0] + ' <b>' + esc(meta[1]) + '</b> · ' + esc(item.sender_name) + (item.deadline ? ' · ⏰ ' + esc(item.deadline) : '') + caseRef(item) + '\n  “' + esc(clip(item.text)) + '”  →  <i>' + esc(meta[2]) + '</i>';
});
const autoLines = grouped['AUTO-HANDLE'].slice(0, 7).map((item) => {
  const meta = intentMeta[item.intent] ?? ['🟡', item.intent, 'Đang theo dõi'];
  return '• ' + meta[0] + ' <b>' + esc(meta[1]) + '</b> · ' + esc(item.sender_name) + ' — ' + esc(clip(item.text, 95)) + (item.deadline ? ' · ⏰ ' + esc(item.deadline) : '') + caseRef(item);
});
const draftLines = grouped['DRAFT-FOR-YOU'].slice(0, 4).map((item) => {
  const draft = item.draft_replies?.[0] ?? 'Mình đã nhận được tin. Mình phản hồi sớm nhé.';
  return '• 💬 <b>' + esc(item.sender_name) + '</b>: “' + esc(clip(item.text, 90)) + '”\n  ↳ <i>' + esc(clip(draft, 120)) + '</i>';
});
const notify = humanLines.length + autoLines.length + draftLines.length > 0;
const summary = 'Zalo brief: ' + grouped['HUMAN-REQUIRED'].length + ' need you, ' + grouped['AUTO-HANDLE'].length + ' tracked, ' + grouped['DRAFT-FOR-YOU'].length + ' drafts, ' + grouped['IGNORE-DIGEST'].length + ' suppressed';
const sections = [];
if (humanLines.length) sections.push('<b>🔴 CẦN BẠN</b>\n' + humanLines.join('\n') + overflow(grouped['HUMAN-REQUIRED'], 5));
if (autoLines.length) sections.push('<b>🟡 ĐANG THEO DÕI</b>\n' + autoLines.join('\n') + overflow(grouped['AUTO-HANDLE'], 7));
if (draftLines.length) sections.push('<b>✍️ BẢN NHÁP</b>\n' + draftLines.join('\n') + overflow(grouped['DRAFT-FOR-YOU'], 4));
const message = '<b>📬 ZALO BRIEF</b>  ·  ' + esc(clock(now)) + '\n' +
  '🔴 ' + grouped['HUMAN-REQUIRED'].length + ' cần bạn  •  🟡 ' + grouped['AUTO-HANDLE'].length + ' theo dõi  •  ✍️ ' + grouped['DRAFT-FOR-YOU'].length + ' nháp  •  🔕 ' + grouped['IGNORE-DIGEST'].length + ' lọc\n\n' +
  sections.join('\n\n') + '\n\n<i>Lần tổng hợp tiếp theo sau 1 giờ.</i>';

let outboxId = null;
let telegramText = null;
if (notify) {
  const entry = {
    id: 'DIGEST-' + Date.now(),
    channel: 'TELEGRAM',
    priority: 'HOURLY',
    text: message,
    created_at: now.toISOString(),
    status: 'WAITING_FOR_CREDENTIAL'
  };
  store.notificationOutbox.push(entry);
  store.notificationOutbox = store.notificationOutbox.slice(-200);
  outboxId = entry.id;
  telegramText = entry.text;
  console.log('ZALO TRIAGE HOURLY OUTBOX', JSON.stringify(entry));
}

const cutoff = now.getTime() - 30 * 24 * 60 * 60 * 1000;
for (const [key, seenAt] of Object.entries(store.seen)) {
  if (new Date(seenAt).getTime() < cutoff) delete store.seen[key];
}
store.last_hourly_run_at = now.toISOString();
if (!notify) return [];

return [{ json: {
  notify,
  summary,
  counts: {
    human_required: grouped['HUMAN-REQUIRED'].length,
    auto_handle: grouped['AUTO-HANDLE'].length,
    draft_for_you: grouped['DRAFT-FOR-YOU'].length,
    ignored_suppressed: grouped['IGNORE-DIGEST'].length,
    total: pending.length
  },
  outbox_id: outboxId,
  telegram_text: telegramText,
  delivery_status: notify ? 'WAITING_FOR_TELEGRAM_CREDENTIAL' : 'NOT_NEEDED',
  ran_at: store.last_hourly_run_at
} }];

const store = $getWorkflowStaticData('global');
const audit = {
  ...$json,
  open_cases: Object.values(store.cases ?? {}).filter((item) => item.status !== 'DONE').length,
  total_cases: Object.keys(store.cases ?? {}).length,
  outbox_depth: (store.notificationOutbox ?? []).filter((item) => item.status === 'WAITING_FOR_CREDENTIAL').length
};
console.log('ZALO TRIAGE AUDIT', JSON.stringify(audit));
return [{ json: audit }];

const store = $getWorkflowStaticData('global');
const outbox = store.notificationOutbox ?? [];
const entry = [...outbox].reverse().find((item) => item.status === 'WAITING_FOR_CREDENTIAL');
if (entry) {
  entry.status = 'SENT';
  entry.sent_at = new Date().toISOString();
  entry.telegram_message_id = $json.message_id ?? null;
}
return [{ json: {
  telegram_sent: true,
  telegram_message_id: $json.message_id ?? null,
  chat_id: $json.chat?.id ?? null,
  outbox_id: entry?.id ?? null,
  sent_at: entry?.sent_at ?? new Date().toISOString()
} }];

const records = $json.records ?? [];
if (!records.length) return [];

const categoryMap = (record) => {
  if (record.lane === 'HUMAN-REQUIRED') {
    if (['poll-choice', 'approval', 'money-decision'].includes(record.intent)) {
      return 'DECISION_REQUIRED';
    }
    return 'ACTION_REQUIRED';
  }
  if (record.lane === 'AUTO-HANDLE') {
    if (record.urgent || record.intent === 'deadline' || record.intent === 'maintenance-incident' || record.intent === 'procurement') {
      return 'ACTION_REQUIRED';
    }
    if (record.intent === 'worker-report') return 'FYI';
    return 'WAITING';
  }
  if (record.lane === 'DRAFT-FOR-YOU') {
    if (record.intent === 'reply-needed') return 'ACTION_REQUIRED';
    return 'FYI';
  }
  return 'IGNORE';
};

const priorityMap = (record) => {
  if (record.urgent || record.lane === 'HUMAN-REQUIRED') return 0.9;
  if (record.lane === 'AUTO-HANDLE') return 0.7;
  if (record.lane === 'DRAFT-FOR-YOU') return 0.5;
  return 0.1;
};

const events = records.map((r) => {
  const category = categoryMap(r);
  const priority = priorityMap(r);
  const cleanSummary = (r.sender_name || 'Unknown') + ': ' + (r.text.length > 200 ? r.text.slice(0, 199) + '…' : r.text);

  return {
    json: {
      event_id: 'zalo:' + r.message_id,
      occurred_at: r.timestamp,
      ingested_at: new Date().toISOString(),
      source: 'zalo',
      event_type: 'message_triage',
      category,
      priority,
      summary: cleanSummary,
      status: 'OPEN',
      source_ref: r.case_id || r.conversation_id || null,
      correlation_id: r.case_id || null,
      metadata: {
        sender_name: r.sender_name,
        sender_role: r.sender_role,
        lane: r.lane,
        intent: r.intent,
        urgent: r.urgent,
        deadline: r.deadline
      }
    }
  };
});

return events;
